SELECT factures.code_client, clients.prenom, clients.nom, COUNT(factures.num_facture) AS nombre_de_location, SUM(mangas.prix_base * types_location.coefficient) AS total_depenses FROM factures JOIN clients ON factures.code_client = clients.code_client JOIN table_location ON factures.num_facture = table_location.num_facture JOIN mangas ON table_location.num_manga = mangas.num_manga JOIN types_location ON table_location.code_type = types_location.code_type GROUP BY clients.code_client ORDER BY total_depenses DESC LIMIT 5;